/* MinifilterTelemetry.c - Compilable with WDK for Windows Server 2019 */

#include <fltKernel.h>
#include <ntddk.h>

#define DRIVER_TAG 'tfMF'
#define ALTITUDE L"370010"
#define DEVICE_NAME L"\\Device\\MinifilterTelemetry"
#define SYMLINK_NAME L"\\??\\MinifilterTelemetry"
#define IOCTL_GET_LOG CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_READ_DATA)

#define MAX_ENTRIES 1024

typedef struct _TELEMETRY_ENTRY {
    UNICODE_STRING FileName;
    LARGE_INTEGER TimeStamp;
} TELEMETRY_ENTRY, *PTELEMETRY_ENTRY;

static TELEMETRY_ENTRY g_LogBuffer[MAX_ENTRIES];
static LONG g_LogIndex = 0;

PFLT_FILTER g_FilterHandle = NULL;
PDEVICE_OBJECT g_DeviceObject = NULL;

/* Forward declarations */
NTSTATUS MiniPreCreate(
    _Inout_ PFLT_CALLBACK_DATA Data,
    _In_ PCFLT_RELATED_OBJECTS FltObjects,
    _Out_ PVOID *CompletionContext);

NTSTATUS MiniPreWrite(
    _Inout_ PFLT_CALLBACK_DATA Data,
    _In_ PCFLT_RELATED_OBJECTS FltObjects,
    _Out_ PVOID *CompletionContext);

NTSTATUS DriverDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP Irp);

/* Callback registration */
CONST FLT_OPERATION_REGISTRATION Callbacks[] = {
    { IRP_MJ_CREATE,
      0,
      MiniPreCreate,
      NULL },
    { IRP_MJ_WRITE,
      0,
      MiniPreWrite,
      NULL },
    { IRP_MJ_OPERATION_END }
};

CONST FLT_REGISTRATION FilterRegistration = {
    sizeof(FLT_REGISTRATION),          // Size
    FLT_REGISTRATION_VERSION,          // Version
    0,                                 // Flags
    NULL,                              // Context
    Callbacks,                         // Operation callbacks
    DriverUnload,                      // FilterUnload
    NULL,                              // InstanceSetup
    NULL,                              // InstanceQueryTeardown
    NULL,                              // InstanceTeardownStart
    NULL,                              // InstanceTeardownComplete
    NULL,                              // GenerateFileName
    NULL,                              // GenerateDestinationFileName
    NULL                               // NormalizeNameComponent
};

/* Pre-create callback */
NTSTATUS MiniPreCreate(
    _Inout_ PFLT_CALLBACK_DATA Data,
    _In_ PCFLT_RELATED_OBJECTS FltObjects,
    _Out_ PVOID *CompletionContext)
{
    UNREFERENCED_PARAMETER(FltObjects);
    UNREFERENCED_PARAMETER(CompletionContext);

    if (Data->Iopb->TargetFileObject) {
        PUNICODE_STRING name = Data->Iopb->TargetFileObject->FileName;
        LONG idx = InterlockedIncrement(&g_LogIndex) - 1;
        if (idx < MAX_ENTRIES) {
            g_LogBuffer[idx].FileName = *name;
            KeQuerySystemTime(&g_LogBuffer[idx].TimeStamp);
        }
    }
    return FLT_PREOP_SUCCESS_NO_CALLBACK;
}

/* Pre-write callback (simple logging) */
NTSTATUS MiniPreWrite(
    _Inout_ PFLT_CALLBACK_DATA Data,
    _In_ PCFLT_RELATED_OBJECTS FltObjects,
    _Out_ PVOID *CompletionContext)
{
    UNREFERENCED_PARAMETER(FltObjects);
    UNREFERENCED_PARAMETER(CompletionContext);
    /* Could log write specifics here; omitted for brevity */
    return FLT_PREOP_SUCCESS_NO_CALLBACK;
}

/* IOCTL handler for user‑mode retrieval */
NTSTATUS DriverDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    PIO_STACK_LOCATION stack = IoGetCurrentIrpStackLocation(Irp);
    NTSTATUS status = STATUS_SUCCESS;
    ULONG outLen = 0;

    switch (stack->Parameters.DeviceIoControl.IoControlCode) {
    case IOCTL_GET_LOG:
        if (stack->Parameters.DeviceIoControl.OutputBufferLength >= sizeof(g_LogBuffer)) {
            RtlCopyMemory(Irp->AssociatedIrp.SystemBuffer, g_LogBuffer, sizeof(g_LogBuffer));
            outLen = sizeof(g_LogBuffer);
        } else {
            status = STATUS_BUFFER_TOO_SMALL;
        }
        break;
    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

    Irp->IoStatus.Status = status;
    Irp->IoStatus.Information = outLen;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* Driver entry */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT DriverObject,
    _In_ PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);
    NTSTATUS status;
    UNICODE_STRING devName = RTL_CONSTANT_STRING(DEVICE_NAME);
    UNICODE_STRING symLink = RTL_CONSTANT_STRING(SYMLINK_NAME);
    UNICODE_STRING altitude = RTL_CONSTANT_STRING(ALTITUDE);

    /* Register the filter */
    status = FltRegisterFilter(DriverObject, &FilterRegistration, &g_FilterHandle);
    if (!NT_SUCCESS(status)) {
        KdPrint(("FltRegisterFilter failed: 0x%x\n", status));
        return status;
    }

    /* Create control device */
    status = IoCreateDevice(
        DriverObject,
        0,
        &devName,
        FILE_DEVICE_UNKNOWN,
        0,
        FALSE,
        &g_DeviceObject);
    if (!NT_SUCCESS(status)) {
        FltUnregisterFilter(g_FilterHandle);
        return status;
    }

    status = IoCreateSymbolicLink(&symLink, &devName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(g_DeviceObject);
        FltUnregisterFilter(g_FilterHandle);
        return status;
    }

    /* Assign all major functions to our IOCTL handler */
    for (UCHAR i = 0; i <= IRP_MJ_MAXIMUM_FUNCTION; i++) {
        DriverObject->MajorFunction[i] = DriverDeviceControl;
    }

    /* Set altitude */
    status = FltSetFilterAltitude(g_FilterHandle, &altitude);
    if (!NT_SUCCESS(status)) {
        IoDeleteSymbolicLink(&symLink);
        IoDeleteDevice(g_DeviceObject);
        FltUnregisterFilter(g_FilterHandle);
        return status;
    }

    /* Start filtering */
    status = FltStartFiltering(g_FilterHandle);
    if (!NT_SUCCESS(status)) {
        IoDeleteSymbolicLink(&symLink);
        IoDeleteDevice(g_DeviceObject);
        FltUnregisterFilter(g_FilterHandle);
        return status;
    }

    KdPrint(("Minifilter telemetry driver loaded.\n"));
    return STATUS_SUCCESS;
}

/* Driver unload */
VOID
DriverUnload(
    _In_ PDRIVER_OBJECT DriverObject)
{
    UNREFERENCED_PARAMETER(DriverObject);
    UNICODE_STRING symLink = RTL_CONSTANT_STRING(SYMLINK_NAME);

    if (g_FilterHandle) {
        FltUnregisterFilter(g_FilterHandle);
    }

    IoDeleteSymbolicLink(&symLink);
    if (g_DeviceObject) {
        IoDeleteDevice(g_DeviceObject);
    }

    KdPrint(("Minifilter telemetry driver unloaded.\n"));
}
```

